#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    double bona = (a + b + c) / 3.0;     // división real
    double dolenta = (a + b + c) / 3;    // división ENTERA: 5 / 3 = 1
    cout << fixed << setprecision(1) << bona << endl;
    cout << fixed << setprecision(1) << dolenta << endl;
    return 0;
}

